    private function do_ibkr_connect() {
        /**
         * opens (or reuses) the authenticated websocket connection, the brokerage $session $cookie is obtained via POST /tickle
         * @ignore
         *
         * @see https://www.interactivebrokers.com/docs/web-api/ws/connection-guide
         * @see https://www.interactivebrokers.com/docs/web-api/ws/auth-status
         *
         * @return {string} the $url of the websocket $client
         */
        Async\await($this->authenticate());
        $useGateway = $this->safe_bool($this->options, 'useGateway', false);
        $url = null;
        if ($useGateway) {
            // wss://api.ibkr.com/v1/api/ws -> wss://localhost:5000/v1/api/ws
            $gatewayUrl = $this->safe_string($this->options, 'gatewayUrl');
            $replacedUrl = str_replace('wss://', 'https://', $this->urls['api']['ws']);
            $restUrl = $this->ibkrGatewayBaseUrl($replacedUrl, $gatewayUrl);
            $url = str_replace('https://', 'wss://', $restUrl);
            $url = str_replace('http://', 'ws://', $url);
        } else {
            // this.apiKey (the oauth consumer key) is unset in gateway mode, concatenating it here would crash in python/php
            $url = $this->urls['api']['ws'] . '?oauth_token=' . $this->apiKey;
        }
        if (!(is_array($this->clients) && array_key_exists($url ?? '', $this->clients))) {
            $response = Async\await($this->webapiPostV1ApiTickle());
            //
            //     { "session": "bb665d0f55b6289d70bc8a7f4fd2d3d0", "iserver": { "authStatus": { "authenticated": true, ... } }, ... }
            //
            $session = $this->safe_string($response, 'session');
            if ($session === null) {
                throw new AuthenticationError($this->id . ' ibkrConnect() POST /tickle returned no session ' . $this->json($response));
            }
            $defaultOptions = array(
                'ws' => array(
                    'options' => array(
                        'headers' => array(),
                    ),
                ),
            );
            $this->extend_exchange_options($defaultOptions);
            $originalHeaders = $this->options['ws']['options']['headers'];
            // with oauth the cookie carries the raw session id (not the {"session":"..."} json used by the
            // client portal gateway) and the upgrade is rejected with http 403 unless the user agent is ClientPortalGW
            $userAgent = $this->safe_string($this->options, 'wsUserAgent', 'ClientPortalGW/1');
            $cookie = 'api=' . $session;
            if ($useGateway) {
                $cookie = 'api=' . $this->json(array( 'session' => $session ));
            }
            $headers = $this->extend($originalHeaders, array(
                'Cookie' => $cookie,
                'User-Agent' => $userAgent,
            ));
            $this->options['ws']['options']['headers'] = $headers;
            // instantiate client
            $newClient = $this->client($url);
            $this->options['ws']['options']['headers'] = $originalHeaders;
            $tickleInterval = $this->safe_integer($this->options, 'tickleInterval', 240000);
            $this->delay($tickleInterval, array($this, 'ibkr_keep_alive_session'), $newClient);
        }
        $client = $this->client($url);
        $awaitAuthenticated = $this->safe_bool($this->options, 'awaitAuthenticated', true);
        $isAuthenticated = $this->safe_bool($client->subscriptions, 'ibkrAuthenticated', false);
        // watch () dials the connection, the raw sends (ibkrSubscribe, ibkrUnsubscribe) need it open
        if ($awaitAuthenticated && !$isAuthenticated) {
            // resolved by the sts message
            $messageHash = 'authenticated';
            Async\await($this->watch($url, $messageHash, null, $messageHash));
        } elseif (!$this->safe_bool($client->subscriptions, 'ibkrConnected', false)) {
            // resolved by the first system message, sent by IBKR right after the connection opens
            $messageHash = 'connected';
            Async\await($this->watch($url, $messageHash, null, $messageHash));
        }
        return $url;
    }

    public function ibkr_keep_alive_session(Client $client): PromiseInterface {
        return Async\async(self::do_ibkr_keep_alive_session(...))($client);
    }

    private function do_ibkr_keep_alive_session(Client $client) {
        /**
         * keeps the brokerage session alive with POST /tickle and refreshes the market data streams, which expire after 15 minutes
         * @ignore
         * @param {array} $client the websocket $client
         * @return {null}
         */
        $current = $this->safe_value($this->clients, $client->url);
        if ($current !== $client) {
            return null; // the connection was closed or replaced
        }
        try {
            Async\await($this->webapiPostV1ApiTickle());
        } catch (Exception $e) {
            // a failing tickle is retried on the next interval
            if ($this->verbose) {
                $this->log('ibkrKeepAliveSession tickle failed ' . $this->exception_message($e));
            }
        }
        // resubscribe the market data streams before they expire
        $sent = array();
        $keys = is_array($client->subscriptions) ? array_keys($client->subscriptions) : array();
        for ($i = 0; $i < count($keys); $i++) {
            $subscription = $client->subscriptions[$keys[$i]];
            if (gettype($subscription) === 'array') {
                $request = $this->safe_string($subscription, 'request');
                if (($request !== null) && str_starts_with($request, 'smd+') && !(is_array($sent) && array_key_exists($request ?? '', $sent))) {
                    $sent[$request] = true;
                    try {
                        Async\await($client->send($request));
                    } catch (Exception $e) {
                        // the connection is gone, the client reconnects on the next watch call
                        if ($this->verbose) {
                            $this->log('ibkrKeepAliveSession resubscribe failed ' . $this->exception_message($e));
                        }
                    }
                }
            }
        }
        $tickleInterval = $this->safe_integer($this->options, 'tickleInterval', 240000);
        $this->delay($tickleInterval, array($this, 'ibkr_keep_alive_session'), $client);
        return null;
    }

    public function ibkr_subscribe(Client $client, string $subscribeHash, string $request, array $subscription = array()): PromiseInterface {
        return Async\async(self::do_ibkr_subscribe(...))($client, $subscribeHash, $request, $subscription);
    }

    private function do_ibkr_subscribe(Client $client, string $subscribeHash, string $request, array $subscription = array()) {
        /**
         * sends a raw $subscription message once per subscribe hash, IBKR does not acknowledge subscriptions
         * @ignore
         * @param {array} $client the websocket $client
         * @param {string} $subscribeHash the key of the $subscription
         * @param {string} $request the raw message, $e->g. 'smd+265598+array("fields":["31"])'
         * @param {array} [$subscription] extra data stored with the $subscription
         * @return {null}
         */
        if (is_array($client->subscriptions) && array_key_exists($subscribeHash ?? '', $client->subscriptions)) {
            return null;
        }
        $client->subscriptions[$subscribeHash] = $this->extend($subscription, array( 'request' => $request ));
        try {
            Async\await($client->send($request));
        } catch (Exception $e) {
            unset($client->subscriptions[$subscribeHash]);
            throw $e;
        }
        return null;
    }

    public function ibkr_unsubscribe(Client $client, array $subHashes, ?string $request, array $subscription = array()): PromiseInterface {
        return Async\async(self::do_ibkr_unsubscribe(...))($client, $subHashes, $request, $subscription);
    }

    private function do_ibkr_unsubscribe(Client $client, array $subHashes, ?string $request, array $subscription = array()) {
        /**
         * removes the subscriptions and rejects the pending futures of the given hashes, then sends the raw unsubscribe message, IBKR does not acknowledge unsubscriptions
         * @ignore
         * @param {array} $client the websocket $client
         * @param {string[]} $subHashes the message hashes and subscribe hashes to clean
         * @param {string} $request the raw unsubscribe message, e.g. 'umd+265598+array()', null to only clean
         * @param {array} [$subscription] the cache to clean, see cleanCache
         * @return {boolean} true
         */
        for ($i = 0; $i < count($subHashes); $i++) {
            $subHash = $subHashes[$i];
            $this->clean_unsubscription($client, $subHash, 'unsubscribe::' . $subHash);
        }
        $this->clean_cache($subscription);
        if ($request !== null) {
            // the connection is open, the callers get the client from ibkrConnect ()
            Async\await($client->send($request));
        }
        return true;
    }

    public function ibkr_unsubscribe_market_data(Client $client, ?string $marketId): PromiseInterface {
