    public function ibkr_watch_market_data(string $topic, ?array $symbols = null, $params = array()): PromiseInterface {
        return Async\async(self::do_ibkr_watch_market_data(...))($topic, $symbols, $params);
    }

    private function do_ibkr_watch_market_data(string $topic, ?array $symbols = null, $params = array()) {
        /**
         * subscribes to the smd streams of the markets
         * @ignore
         * @param {string} $topic 'ticker' or 'bidask'
         * @param {string[]} $symbols unified $symbols of the markets
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} the updated $ticker
         */
        Async\await($this->load_markets());
        $marketSymbols = $this->market_symbols($symbols, null, false);
        $url = Async\await($this->ibkr_connect());
        $client = $this->client($url);
        $messageHashes = array();
        for ($i = 0; $i < count($marketSymbols); $i++) {
            $messageHashes[] = $topic . '::' . $marketSymbols[$i];
        }
        // the futures are created before the raw sends, so no update can be missed in between,
        // reusableFuture (), not watchMultiple () - the connection is already open (ibkrConnect), and go's watch* yields a channel
        $futures = array();
        for ($i = 0; $i < count($messageHashes); $i++) {
            $futures[] = $client->reusableFuture($messageHashes[$i]);
        }
        for ($i = 0; $i < count($marketSymbols); $i++) {
            $market = $this->market($marketSymbols[$i]);
            list($request, $query) = $this->ibkr_market_data_request($market['id'], $params);
            $subscription = $this->extend(array( 'conid' => $market['id'], 'symbol' => $market['symbol'] ), $query);
            Async\await($this->ibkr_subscribe($client, $messageHashes[$i], $request, $subscription));
        }
        $ticker = Async\await($this->watch_multiple($url, $messageHashes));
        return $ticker;
    }

