    }

    private function do_ibkr_un_watch_market_data(string $topic, ?array $symbols = null, $params = array()) {
        /**
         * removes the ticker or bidask subscriptions, umd is sent when the $market has no other $subscription left
         * @ignore
         * @param {string} $topic 'ticker' or 'bidask'
         * @param {string[]} $symbols unified $symbols of the markets
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {boolean} true
         */
        Async\await($this->load_markets());
        $marketSymbols = $this->market_symbols($symbols, null, false);
        $url = Async\await($this->ibkr_connect());
        $client = $this->client($url);
        $subHashes = array();
        for ($i = 0; $i < count($marketSymbols); $i++) {
            $subHashes[] = $topic . '::' . $marketSymbols[$i];
        }
        $subscription = array(
            'topic' => ($topic === 'bidask') ? 'bidsasks' : 'ticker', // the cache names of cleanCache
            'symbols' => $marketSymbols,
        );
        Async\await($this->ibkr_unsubscribe($client, $subHashes, null, $subscription));
        for ($i = 0; $i < count($marketSymbols); $i++) {
            $market = $this->market($marketSymbols[$i]);
            Async\await($this->ibkr_unsubscribe_market_data($client, $market['id']));
        }
        return true;
    }

    public function handle_ticker(Client $client, array $message) {
        //
        //     {
        //         "server_id": "q0",
        //         "conidEx": "495759171",
        //         "conid": 495759171,
        //         "_updated": 1702334859712,
        //         "6119": "q0",
        //         "31": "2428.50",
        //         "84": "2428.25",
        //         "86": "2428.75",
        //         "topic": "smd+495759171"
        //     }
        //
        $topic = $this->safe_string($message, 'topic', '');
        $parts = explode('+', $topic);
        $marketId = $this->safe_string($parts, 1);
        $market = $this->safe_market($marketId);
        $symbol = $market['symbol'];
        // the updates are deltas (only the changed fields are sent), they are merged into the previous raw ticker,
        // the bidsasks cache is the fallback in case the tickers cache was cleaned by unWatchTickers
        $previous = $this->safe_dict($this->tickers, $symbol);
        if ($previous === null) {
            $previous = $this->safe_dict($this->bidsasks, $symbol, array());
        }
        $previousInfo = $this->safe_dict($previous, 'info', array());
        $merged = $this->extend($previousInfo, $message);
        if ($this->safe_integer($message, '_updated') === null) {
            $merged['_updated'] = $this->milliseconds();
        }
        $ticker = $this->parse_ticker($merged, $market);
        $this->tickers[$symbol] = $ticker;
        $client->resolve($ticker, 'ticker::' . $symbol);
        // a delta without bid/ask fields (e.g. only the mark price 7635) does not change the best bid and ask,
        // and nothing is emitted to watchBidsAsks until a bid or an ask has been received
        $hasBidAsk = (is_array($message) && array_key_exists('84' ?? '', $message)) || (is_array($message) && array_key_exists('85' ?? '', $message)) || (is_array($message) && array_key_exists('86' ?? '', $message)) || (is_array($message) && array_key_exists('88' ?? '', $message));
        $hasQuote = ($ticker['bid'] !== null) || ($ticker['ask'] !== null);
        if ($hasBidAsk && $hasQuote) {
            $bidAsk = $this->safe_ticker(array(
                'symbol' => $symbol,
                'timestamp' => $ticker['timestamp'],
                'datetime' => $ticker['datetime'],
                'bid' => $this->safe_string($ticker, 'bid'),
                'bidVolume' => $this->safe_string($ticker, 'bidVolume'),
                'ask' => $this->safe_string($ticker, 'ask'),
                'askVolume' => $this->safe_string($ticker, 'askVolume'),
                'info' => $merged,
            ), $market);
            $this->bidsasks[$symbol] = $bidAsk;
            $client->resolve($bidAsk, 'bidask::' . $symbol);
        }
        $this->ibkr_update_ohlcvs($client, $symbol, $message);
    }

    public function watch_ohlcv(string $symbol, string $timeframe = '1m', ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
