    private function do_watch_ohlcv(string $symbol, string $timeframe = '1m', ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * watches historical candlestick data containing the open, high, low, and close price, and the volume of a $market, the history comes from smh, the last candles are built from the last price of the smd stream
         *
         * @see https://www.interactivebrokers.com/docs/web-api/ws/historical-data
         * @see https://www.interactivebrokers.com/docs/web-api/ws/streaming-data
         *
         * @param {string} $symbol unified $symbol of the $market to fetch OHLCV data for
         * @param {string} $timeframe the length of time each candle represents
         * @param {int} [$since] timestamp in ms of the earliest candle to fetch
         * @param {int} [$limit] the maximum amount of candles to fetch
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->source] 'trades' (default), 'midpoint', 'bid_ask', 'bid' or 'ask'
         * @param {boolean} [$params->outsideRth] include data outside regular trading hours
         * @return {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $unifiedSymbol = $market['symbol'];
        $url = Async\await($this->ibkr_connect());
        $client = $this->client($url);
        $messageHash = 'ohlcv::' . $unifiedSymbol . '::' . $timeframe;
        // reusableFuture (), not watch () - the connection is already open (ibkrConnect), and go's watch () yields a channel
        $future = $client->reusableFuture($messageHash);
        // the last price stream, it builds the current candles
        list($marketDataRequest, $query) = $this->ibkr_market_data_request($market['id'], $params);
        Async\await($this->ibkr_subscribe($client, $messageHash, $marketDataRequest, array( 'conid' => $market['id'], 'symbol' => $unifiedSymbol, 'timeframe' => $timeframe )));
        // the history, it seeds the candles
        $historyHash = 'smh::' . $market['id'] . '::' . $timeframe;
        if (!(is_array($client->subscriptions) && array_key_exists($historyHash ?? '', $client->subscriptions))) {
            if (!(is_array($this->ohlcvs) && array_key_exists($unifiedSymbol ?? '', $this->ohlcvs))) {
                $this->ohlcvs[$unifiedSymbol] = array();
            }
            $ohlcvLimit = $this->safe_integer($this->options, 'OHLCVLimit', 1000);
            if (!(is_array($this->ohlcvs[$unifiedSymbol]) && array_key_exists($timeframe ?? '', $this->ohlcvs[$unifiedSymbol]))) {
                $this->ohlcvs[$unifiedSymbol][$timeframe] = new ArrayCacheByTimestamp($ohlcvLimit);
            }
            $options = $this->safe_dict($this->options, 'watchOHLCV', array());
            $duration = $this->parse_timeframe($timeframe);
            $historyLimit = ($limit === null) ? 100 : $limit;
            $historyRequest = array(
                'exchange' => $this->safe_string($options, 'exchange', 'SMART'),
                'period' => $this->ibkr_ws_period($duration, $historyLimit),
                'bar' => $this->safe_string($this->timeframes, $timeframe, $timeframe),
                'outsideRth' => $this->safe_bool($options, 'outsideRth', false),
                'source' => $this->safe_string($options, 'source', 'trades'),
                // no 'format', the bars carry the "t" timestamp only with the default format
            );
            // keysort: the dict key order is not preserved in every language (java HashMap), the raw frame must be identical
            $request = 'smh+' . $market['id'] . '+' . $this->json($this->keysort($this->extend($historyRequest, $query)));
            Async\await($this->ibkr_subscribe($client, $historyHash, $request, array( 'conid' => $market['id'], 'symbol' => $unifiedSymbol, 'timeframe' => $timeframe, 'duration' => $duration )));
        }
        $ohlcv = Async\await($future);
        $resultLimit = $limit;
        if ($this->newUpdates) {
            $resultLimit = $ohlcv->getLimit($unifiedSymbol, $limit);
        }
        return $this->filter_by_since_limit($ohlcv, $since, $resultLimit, 0, true);
    }

    public function un_watch_ohlcv(string $symbol, string $timeframe = '1m', $params = array()): PromiseInterface {
        return Async\async(self::do_un_watch_ohlcv(...))($symbol, $timeframe, $params);
    }

    private function do_un_watch_ohlcv(string $symbol, string $timeframe = '1m', $params = array()) {
        /**
         * unWatches historical candlestick data
         *
         * @see https://www.interactivebrokers.com/docs/web-api/ws/streaming-data
         *
         * @param {string} $symbol unified $symbol of the $market
         * @param {string} $timeframe the length of time each candle represents
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {boolean} true
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $unifiedSymbol = $market['symbol'];
        $url = Async\await($this->ibkr_connect());
        $client = $this->client($url);
        $subHashes = array( 'ohlcv::' . $unifiedSymbol . '::' . $timeframe, 'smh::' . $market['id'] . '::' . $timeframe );
        $subscription = array(
            'topic' => 'ohlcv',
            'symbolsAndTimeframes' => array( array( $unifiedSymbol, $timeframe ) ),
        );
        Async\await($this->ibkr_unsubscribe($client, $subHashes, null, $subscription));
        Async\await($this->ibkr_unsubscribe_market_data($client, $market['id']));
        return true;
    }

    public function handle_ohlcv(Client $client, array $message) {
        //
        //     {
        //         "serverId": "smh265598",
        //         "symbol": "AAPL",
        //         "barLength": 3600,
        //         "data": [
        //             { "o": 182.0, "c": 183.5, "h": 184.2, "l": 181.5, "v": 95000, "t": 1699801200 }
        //         ],
        //         "points": 1,
        //         "topic": "smh+265598"
        //     }
        //
        $topic = $this->safe_string($message, 'topic', '');
        $parts = explode('+', $topic);
        $marketId = $this->safe_string($parts, 1);
        $serverId = $this->safe_string($message, 'serverId');
        if ($serverId !== null) {
            // the history is sent once, the request must be cancelled to free one of the 5 concurrent slots
            $this->spawn(array($this, 'ibkr_cancel_history'), $client, $serverId);
        }
        $barLength = $this->safe_integer($message, 'barLength');
        // several timeframes of a market share the topic, they are told apart by the bar length
        $keys = is_array($client->subscriptions) ? array_keys($client->subscriptions) : array();
        $subscription = null;
        for ($i = 0; $i < count($keys); $i++) {
            $key = $keys[$i];
            // the base watch () stores internal futures (connected/authenticated) under an undefined
            // subscription hash, which is a None dict key in python, so it cannot be assumed a string
            if (($key !== null) && str_starts_with($key, 'smh::' . $marketId . '::')) {
                $candidate = $client->subscriptions[$key];
                $duration = $this->safe_integer($candidate, 'duration');
                if (($subscription === null) || ($duration === $barLength)) {
                    $subscription = $candidate;
                }
            }
        }
        if ($subscription === null) {
            return;
        }
        $symbol = $this->safe_string($subscription, 'symbol');
        $timeframe = $this->safe_string($subscription, 'timeframe');
        $market = $this->safe_market($marketId);
        $stored = $this->safe_value($this->safe_dict($this->ohlcvs, $symbol, array()), $timeframe);
        if ($stored === null) {
            return;
        }
        $data = $this->safe_list($message, 'data', array());
        $bars = array();
        $lastHistoryTimestamp = null;
        for ($i = 0; $i < count($data); $i++) {
            $parsed = $this->parse_ohlcv($data[$i], $market);
            $timestamp = $parsed[0];
            if ($timestamp === null) {
                continue;
            }
            if ($timestamp < 100000000000) {
                $timestamp = $timestamp * 1000; // seconds
                $parsed[0] = $timestamp;
            }
            $bars[] = $parsed;
            if (($lastHistoryTimestamp === null) || ($timestamp > $lastHistoryTimestamp)) {
                $lastHistoryTimestamp = $timestamp;
            }
        }
        // the live candles built from smd before the history arrived are kept only when they are newer than the history
        for ($i = 0; $i < count($stored); $i++) {
            $candle = $stored[$i];
            if (($lastHistoryTimestamp === null) || ($candle[0] > $lastHistoryTimestamp)) {
                $bars[] = $candle;
            }
        }
        $sorted = $this->sort_by($bars, 0);
        $ohlcvLimit = $this->safe_integer($this->options, 'OHLCVLimit', 1000);
        $this->ohlcvs[$symbol][$timeframe] = new ArrayCacheByTimestamp($ohlcvLimit);
        $cache = $this->ohlcvs[$symbol][$timeframe];
        for ($i = 0; $i < count($sorted); $i++) {
            $cache->append($sorted[$i]);
        }
        $client->resolve($cache, 'ohlcv::' . $symbol . '::' . $timeframe);
    }

    public function ibkr_ws_period(float $duration, float $limit): string {
        /**
         * builds the smh period, it accepts {1-30}min, {1-8}h, {1-1000}d, {1-792}w, {1-182}m and {1-15}y only, so the period is rounded up to the smallest fitting unit
         * @ignore
         *
         * @see https://www.interactivebrokers.com/docs/web-api/ws/historical-data
         *
         * @param {int} $duration the length of one bar in seconds
         * @param {int} $limit the number of bars
         * @return {string} the period, e.g. '2h'
         */
        $total = $duration * $limit;
        $minutes = $this->parse_to_int(($total + 59) / 60);
        if ($minutes <= 30) {
            return $this->number_to_string(max($minutes, 1)) . 'min';
        }
        $hours = $this->parse_to_int(($total + 3599) / 3600);
        if ($hours <= 8) {
            return $this->number_to_string($hours) . 'h';
        }
        $days = $this->parse_to_int(($total + 86399) / 86400);
        if ($days <= 1000) {
            return $this->number_to_string($days) . 'd';
        }
        $weeks = $this->parse_to_int(($total + 604799) / 604800);
        if ($weeks <= 792) {
            return $this->number_to_string($weeks) . 'w';
        }
        $months = $this->parse_to_int(($total + 2591999) / 2592000);
        if ($months <= 182) {
            return $this->number_to_string($months) . 'm';
        }
        $years = $this->parse_to_int(($total + 31535999) / 31536000);
        return $this->number_to_string(min($years, 15)) . 'y';
    }

    public function ibkr_cancel_history(Client $client, string $serverId): PromiseInterface {
        return Async\async(self::do_ibkr_cancel_history(...))($client, $serverId);
    }

    private function do_ibkr_cancel_history(Client $client, string $serverId) {
        /**
         * cancels a historical data request with umh
         * @ignore
         * @param {array} $client the websocket $client
         * @param {string} $serverId the $serverId of the smh response
         * @return {null}
         */
        Async\await($client->send('umh+' . $serverId));
        return null;
    }

    public function ibkr_update_ohlcvs(Client $client, string $symbol, array $delta) {
        /**
         * updates the current candles of the watched $timeframes of a market with the last $price of a market data $delta
         * @ignore
         * @param {array} $client the websocket $client
         * @param {string} $symbol unified market $symbol
         * @param {array} $delta the raw smd message
         */
        $lastString = $this->ibkrParseValue($this->safe_string($delta, '31'));
        if ($lastString === null) {
            return;
        }
        $ohlcvsBySymbol = $this->safe_dict($this->ohlcvs, $symbol);
        if ($ohlcvsBySymbol === null) {
            return;
        }
        $price = $this->parse_number($lastString);
        $sizeString = $this->ibkrParseValue($this->safe_string($delta, '7059'));
        $size = 0;
        if ($sizeString !== null) {
            $size = $this->parse_number($sizeString);
        }
        $timestamp = $this->safe_integer($delta, '_updated', $this->milliseconds());
        $timeframes = is_array($ohlcvsBySymbol) ? array_keys($ohlcvsBySymbol) : array();
        for ($i = 0; $i < count($timeframes); $i++) {
            $timeframe = $timeframes[$i];
            $stored = $ohlcvsBySymbol[$timeframe];
            $duration = $this->parse_timeframe($timeframe) * 1000;
            $candleTimestamp = $this->parse_to_int($timestamp / $duration) * $duration;
            $length = count($stored);
            $candle = null;
            if ($length > 0) {
                $lastCandle = $stored[$length - 1];
                if ($lastCandle[0] === $candleTimestamp) {
                    $candle = $lastCandle;
                } elseif ($lastCandle[0] > $candleTimestamp) {
                    continue;
                }
            }
            if ($candle === null) {
                $stored->append(array( $candleTimestamp, $price, $price, $price, $price, $size ));
            } else {
                $high = max($candle[2], $price);
                $low = min($candle[3], $price);
                $volume = $this->sum($candle[5], $size);
                $stored->append(array( $candleTimestamp, $candle[1], $high, $low, $price, $volume ));
            }
            $client->resolve($stored, 'ohlcv::' . $symbol . '::' . $timeframe);
        }
    }

    public function watch_order_book(string $symbol, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_watch_order_book(...))($symbol, $limit, $params);
    }

    private function do_watch_order_book(string $symbol, ?int $limit = null, $params = array()) {
        /**
         * watches information on open orders with bid (buy) and ask (sell) prices, volumes and other data, requires a level 2 $market data subscription, one price ladder per account
         *
         * @see https://www.interactivebrokers.com/docs/web-api/ws/booktrader
         *
         * @param {string} $symbol unified $symbol of the $market to fetch the order book for
         * @param {int} [$limit] the maximum amount of order book entries to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->accountId] the account id, defaults to options["accountId"]
         * @param {string} [$params->exchange] the deep book exchange, all by default
         * @return {array} A dictionary of ~@link https://docs.ccxt.com/?id=order-book-structure order book structures~ indexed by $market symbols
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $unifiedSymbol = $market['symbol'];
        list($accountId, $query) = Async\await($this->loadAccountId($params));
        $bookExchange = $this->safe_string($query, 'exchange');
        $url = Async\await($this->ibkr_connect());
        $client = $this->client($url);
        $messageHash = 'orderbook::' . $unifiedSymbol;
        // reusableFuture (), not watch () - the connection is already open (ibkrConnect), and go's watch () yields a channel
        $future = $client->reusableFuture($messageHash);
        $request = 'sbd+' . $accountId . '+' . $market['id'];
        if ($bookExchange !== null) {
            $request = $request . '+' . $bookExchange;
        }
        Async\await($this->ibkr_subscribe($client, $messageHash, $request, array( 'conid' => $market['id'], 'symbol' => $unifiedSymbol, 'accountId' => $accountId )));
        $orderbook = Async\await($future);
        return $orderbook->limit();
    }

    public function un_watch_order_book(string $symbol, $params = array()): PromiseInterface {
        return Async\async(self::do_un_watch_order_book(...))($symbol, $params);
    }

    private function do_un_watch_order_book(string $symbol, $params = array()) {
        /**
         * unWatches the order book of a $market, ubd cancels the price ladder of the account
         *
         * @see https://www.interactivebrokers.com/docs/web-api/ws/booktrader
         *
         * @param {string} $symbol unified $symbol of the $market
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->accountId] the account id, defaults to options["accountId"]
         * @return {boolean} true
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $unifiedSymbol = $market['symbol'];
        list($accountId, $query) = Async\await($this->loadAccountId($params));
        $url = Async\await($this->ibkr_connect());
        $client = $this->client($url);
        $subscription = $this->extend(array(
            'topic' => 'orderbook',
            'symbols' => array( $unifiedSymbol ),
        ), $query);
        return Async\await($this->ibkr_unsubscribe($client, array( 'orderbook::' . $unifiedSymbol ), 'ubd+' . $accountId, $subscription));
    }

    public function handle_order_book(Client $client, array $message) {
        //
        // the price ladder is a list of rows, the first message after subscribing is an empty placeholder ladder,
        // then the full ladder is sent, then only the changed rows are sent, every row carries its full state
        // (a row without "bid" or "ask" has no size on that side), when the price moves out of the ladder all the rows are re-sent
        //
        //     {
        //         "topic": "sbd+U1234567+265598",
        //         "data": [
        //             { "row": 0, "focus": 0, "price": "182.45" },
        //             { "row": 1, "focus": 1, "price": "5 @ 182.50" },
        //             { "row": 2, "focus": 0, "price": "182.50", "bid": "200" },
        //             { "row": 3, "focus": 0, "price": "182.55", "ask": "150" }
        //         ]
        //     }
        //
        //     { "topic": "sbd+U1234567+265598", "data": [ { "row": 14, "focus": 0, "price": "182.40", "bid": "22.2274" } ] }
        //
        $topic = $this->safe_string($message, 'topic', '');
        $parts = explode('+', $topic);
        $marketId = $this->safe_string($parts, 2);
        $market = $this->safe_market($marketId);
        $symbol = $market['symbol'];
        $messageHash = 'orderbook::' . $symbol;
        $subscription = $this->safe_dict($client->subscriptions, $messageHash);
        if ($subscription === null) {
            return; // unsubscribed
        }
        // the ladder state, indexed by row, the 'r' prefix keeps the keys strings (php turns numeric string keys into
        // integer keys, which are renumbered when the dict is copied)
        $ladder = $this->safe_dict($subscription, 'ladder', array());
        $data = $this->safe_list($message, 'data', array());
        for ($i = 0; $i < count($data); $i++) {
            $entry = $data[$i];
            $rowNumber = $this->safe_string($entry, 'row');
            if ($rowNumber === null) {
                continue;
            }
            $rowId = 'r' . $rowNumber;
            $price = $this->safe_string($entry, 'price');
            if ($price === null) {
                $previousRow = $this->safe_dict($ladder, $rowId, array());
                $price = $this->safe_string($previousRow, 'price');
            }
            $ladder[$rowId] = array(
                'price' => $price,
                'bid' => $this->safe_string($entry, 'bid'),
                'ask' => $this->safe_string($entry, 'ask'),
            );
        }
        $subscription['ladder'] = $ladder;
        // the order book is rebuilt from all the rows of the ladder
        $bids = array();
        $asks = array();
        $rowIds = is_array($ladder) ? array_keys($ladder) : array();
        for ($i = 0; $i < count($rowIds); $i++) {
            $row = $ladder[$rowIds[$i]];
            $rawPrice = $this->safe_string($row, 'price');
            if ($rawPrice === null) {
                continue;
            }
            if (mb_strpos($rawPrice, '@') !== false) {
                // "size @ price" marks the last trade
                $priceParts = explode('@', $rawPrice);
                $pricePart = $priceParts[1];
                $priceWords = explode(' ', $pricePart);
                $rawPrice = implode('', $priceWords);
            }
            $price = $this->ibkrParseValue($rawPrice);
            if ($price === null) {
                continue;
            }
            $bid = $this->ibkrParseValue($this->safe_string($row, 'bid'));
            $ask = $this->ibkrParseValue($this->safe_string($row, 'ask'));
            if ($bid !== null) {
                $bids[] = array( $price, $bid );
            }
            if ($ask !== null) {
                $asks[] = array( $price, $ask );
            }
        }
        // the placeholder ladder sent right after subscribing has no sizes, it is not emitted
        $bidsLength = count($bids);
        $asksLength = count($asks);
        $isEmpty = ($bidsLength === 0) && ($asksLength === 0);
        $emitted = $this->safe_bool($subscription, 'emitted', false);
        if ($isEmpty && !$emitted) {
            $client->subscriptions[$messageHash] = $subscription;
            return;
        }
        // the first filled ladders carry only the best bid and ask, the deeper sizes arrive a few seconds later,
        // the top-of-book-only ladders are skipped until a deeper level arrives or skipFirstItemTimeout elapses
        if (!$emitted) {
            $options = $this->safe_dict($this->options, 'watchOrderBook', array());
            $skipFirstItem = $this->safe_bool($options, 'skipFirstItem', true);
            $isTopOfBookOnly = ($bidsLength <= 1) && ($asksLength <= 1);
            if ($skipFirstItem && $isTopOfBookOnly) {
                $now = $this->milliseconds();
                $firstFilled = $this->safe_integer($subscription, 'firstFilled', $now);
                $subscription['firstFilled'] = $firstFilled;
                $client->subscriptions[$messageHash] = $subscription;
                $skipTimeout = $this->safe_integer($options, 'skipFirstItemTimeout', 10000);
                if (($now - $firstFilled) < $skipTimeout) {
                    return;
                }
            }
        }
        $subscription['emitted'] = true;
        $client->subscriptions[$messageHash] = $subscription;
        $timestamp = $this->milliseconds();
        $snapshot = $this->parse_order_book(array( 'bids' => $bids, 'asks' => $asks ), $symbol, $timestamp);
        $orderbook = $this->safe_value($this->orderbooks, $symbol);
        if ($orderbook === null) {
            $orderbook = $this->order_book(array());
            $this->orderbooks[$symbol] = $orderbook;
        }
        $orderbook->reset($snapshot);
        $client->resolve($orderbook, $messageHash);
    }

    public function watch_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_watch_orders(...))($symbol, $since, $limit, $params);
    }

    private function do_watch_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * watches information on multiple $orders made by the user
         *
         * @see https://www.interactivebrokers.com/docs/web-api/ws/order-updates
         *
         * @param {string} [$symbol] unified market $symbol of the market the $orders were made in
         * @param {int} [$since] the earliest time in ms to fetch $orders for
         * @param {int} [$limit] the maximum number of order structures to retrieve
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string[]} [$params->filters] order status $filters, e.g. array( 'Submitted', 'Filled' )
         * @return {array[]} a list of ~@link https://docs.ccxt.com/?id=order-structure order structures~
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-orders/get-live-$orders
         *
         */
        Async\await($this->load_markets());
        $messageHash = 'orders';
        $unifiedSymbol = null;
        if ($symbol !== null) {
            $watchOrdersOptions = $this->safe_dict($this->options, 'watchOrders', array());
            $warnIfWithoutSymbol = $this->safe_bool($watchOrdersOptions, 'warnIfWithoutSymbol', true);
            if ($warnIfWithoutSymbol) {
                throw new ExchangeError($this->id . ' watchOrders() with a symbol argument can miss order updates => the orders from previous sessions are not fetched, and the sor updates of the orders not created on this connection carry only the orderId and the status (no conid), so they can not be matched to a symbol. It is recommended to call watchOrders() without the symbol argument and filter the results by symbol. To proceed with the symbol argument anyway and acknowledge this, set exchange.options["watchOrders"]["warnIfWithoutSymbol"] = false');
            }
            $unifiedSymbol = $this->symbol($symbol);
            $messageHash = $messageHash . '::' . $unifiedSymbol;
        }
        $url = Async\await($this->ibkr_connect());
        $client = $this->client($url);
        // the sor updates of the orders that were not created on this connection carry only the orderId and the status,
        // the full raw orders are seeded from the rest snapshot, the updates are merged into them by orderId
        $rawOrders = array();
        if (!(is_array($client->subscriptions) && array_key_exists('sor' ?? '', $client->subscriptions))) {
            $options = $this->safe_dict($this->options, 'watchOrders', array());
            $fetchOrdersSnapshot = $this->safe_bool($options, 'fetchOrdersSnapshot', true);
            if ($fetchOrdersSnapshot) {
                $snapshot = Async\await($this->fetchLiveOrdersRaw());
                for ($i = 0; $i < count($snapshot); $i++) {
                    $rawOrder = $snapshot[$i];
                    $orderId = $this->safe_string($rawOrder, 'orderId');
                    if ($orderId !== null) {
                        $rawOrders[$orderId] = $rawOrder;
                    }
                }
            }
        }
        // reusableFuture (), not watch () - the connection is already open (ibkrConnect), and go's watch () yields a channel
        $future = $client->reusableFuture($messageHash);
        $filters = $this->safe_list($params, 'filters');
        // an empty dict is json-encoded as [] in php, so the empty arguments are sent as a literal
        $requestArgs = '{}';
        if ($filters !== null) {
            $requestParams = array(
                'filters' => $filters,
            );
            $requestArgs = $this->json($requestParams);
        }
        Async\await($this->ibkr_subscribe($client, 'sor', 'sor+' . $requestArgs, array( 'rawOrders' => $rawOrders )));
        $orders = Async\await($future);
        $resultLimit = $limit;
        if ($this->newUpdates) {
            $resultLimit = $orders->getLimit($unifiedSymbol, $limit);
        }
        return $this->filter_by_symbol_since_limit($orders, $unifiedSymbol, $since, $resultLimit, true);
    }

    public function un_watch_orders(?string $symbol = null, $params = array()): PromiseInterface {
        return Async\async(self::do_un_watch_orders(...))($symbol, $params);
    }

    private function do_un_watch_orders(?string $symbol = null, $params = array()) {
        /**
         * unWatches information on multiple orders made by the user
         *
         * @see https://www.interactivebrokers.com/docs/web-api/ws/order-updates
         *
         * @param {string} [$symbol] not used by interactivebrokers.unWatchOrders, all the order streams are cancelled
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {boolean} true
         */
        $url = Async\await($this->ibkr_connect());
        $client = $this->client($url);
        $this->clean_unsubscription($client, 'orders', 'unsubscribe::orders', true);
        $emptyArgs = '{}'; // a separate literal, the php transpiler turns '+{}' into '+array()'
        return Async\await($this->ibkr_unsubscribe($client, array( 'sor' ), 'uor+' . $emptyArgs, array( 'topic' => 'orders' )));
    }

    public function handle_orders(Client $client, array $message) {
        //
        //     {
        //         "topic": "sor",
        //         "args": [
        //             {
        //                 "acct": "U1234567",
        //                 "conid": 265598,
        //                 "orderId": 1234568790,
        //                 "orderType": "Limit",
        //                 "side": "BUY",
        //                 "price": "185.50",
        //                 "status": "Submitted",
        //                 "filledQuantity": 0.0,
        //                 "remainingQuantity": 5.0,
        //                 "totalSize": 5.0,
        //                 "timeInForce": "CLOSE",
        //                 "lastExecutionTime_r": 1702317649000,
        //                 "order_ref": "my-id"
        //             }
        //         ]
        //     }
        //
        $args = $this->safe_list($message, 'args', array());
        $argsLength = count($args);
        if ($argsLength === 0) {
            return;
        }
        if ($this->orders === null) {
            $limit = $this->safe_integer($this->options, 'ordersLimit', 1000);
            $this->orders = new ArrayCacheBySymbolById($limit);
        }
        $orders = $this->orders;
        // the updates are partial, e.g. { "acct": "U1234567", "orderId": 1911471157, "status": "Cancelled" } without the conid,
        // they are merged into the previous raw order of the same orderId
        $subscription = $this->safe_dict($client->subscriptions, 'sor');
        $rawOrders = $this->safe_dict($subscription, 'rawOrders', array());
        $symbols = array();
        for ($i = 0; $i < count($args); $i++) {
            $rawOrder = $args[$i];
            $orderId = $this->safe_string($rawOrder, 'orderId');
            $merged = $rawOrder;
            if ($orderId !== null) {
                $previous = $this->safe_dict($rawOrders, $orderId, array());
                $merged = $this->extend($previous, $rawOrder);
                $rawOrders[$orderId] = $merged;
            }
            $parsed = $this->parse_order($merged);
            $orders->append($parsed);
            $orderSymbol = $parsed['symbol'];
            if ($orderSymbol !== null) {
                $symbols[$orderSymbol] = true;
            }
        }
        if ($subscription !== null) {
            $subscription['rawOrders'] = $rawOrders;
            $client->subscriptions['sor'] = $subscription;
        }
        $client->resolve($orders, 'orders');
        $keys = is_array($symbols) ? array_keys($symbols) : array();
        for ($i = 0; $i < count($keys); $i++) {
            $client->resolve($orders, 'orders::' . $keys[$i]);
        }
    }

    public function watch_my_trades(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_watch_my_trades(...))($symbol, $since, $limit, $params);
    }

    private function do_watch_my_trades(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * watches information on multiple $trades made by the user
         *
         * @see https://www.interactivebrokers.com/docs/web-api/ws/trades
         *
         * @param {string} [$symbol] unified market $symbol of the market the $trades were made in
         * @param {int} [$since] the earliest time in ms to fetch $trades for
         * @param {int} [$limit] the maximum number of trade structures to retrieve
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {boolean} [$params->realtimeUpdatesOnly] return only the executions made after subscribing, default true, false also returns the executions of the last $params->days days, the filtering is done $client-side
         * @param {int} [$params->days] number of days of past executions requested on subscribing, default 1
         * @return {array[]} a list of ~@link https://docs.ccxt.com/?id=trade-structure trade structures~
         */
        Async\await($this->load_markets());
        $messageHash = 'myTrades';
        $unifiedSymbol = null;
        if ($symbol !== null) {
            $unifiedSymbol = $this->symbol($symbol);
            $messageHash = $messageHash . '::' . $unifiedSymbol;
        }
        $url = Async\await($this->ibkr_connect());
        $client = $this->client($url);
        // reusableFuture (), not watch () - the connection is already open (ibkrConnect), and go's watch () yields a channel
        $future = $client->reusableFuture($messageHash);
        $options = $this->safe_dict($this->options, 'watchMyTrades', array());
        $realtimeUpdatesOnly = $this->safe_bool($params, 'realtimeUpdatesOnly', $this->safe_bool($options, 'realtimeUpdatesOnly', true));
        // the server handles realtimeUpdatesOnly=true unreliably, sometimes it replays the executions of the last days anyway,
        // sometimes it sends no executions at all (not even the new ones), so the stream is always requested with
        // realtimeUpdatesOnly=false and the executions older than the subscription are dropped on the client side instead
        $requestParams = array(
            'realtimeUpdatesOnly' => false,
            'days' => $this->safe_integer($params, 'days', $this->safe_integer($options, 'days', 1)),
        );
        $subscription = array(
            'realtimeUpdatesOnly' => $realtimeUpdatesOnly,
            'subscribedAt' => $this->milliseconds(),
        );
        Async\await($this->ibkr_subscribe($client, 'str', 'str+' . $this->json($requestParams), $subscription));
        $trades = Async\await($future);
        $resultLimit = $limit;
        if ($this->newUpdates) {
            $resultLimit = $trades->getLimit($unifiedSymbol, $limit);
        }
        return $this->filter_by_symbol_since_limit($trades, $unifiedSymbol, $since, $resultLimit, true);
    }

    public function un_watch_my_trades(?string $symbol = null, $params = array()): PromiseInterface {
        return Async\async(self::do_un_watch_my_trades(...))($symbol, $params);
    }

    private function do_un_watch_my_trades(?string $symbol = null, $params = array()) {
        /**
         * unWatches information on multiple trades made by the user
         *
         * @see https://www.interactivebrokers.com/docs/web-api/ws/trades
         *
         * @param {string} [$symbol] not used by interactivebrokers.unWatchMyTrades, all the trade streams are cancelled
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {boolean} true
         */
        $url = Async\await($this->ibkr_connect());
        $client = $this->client($url);
        $this->clean_unsubscription($client, 'myTrades', 'unsubscribe::myTrades', true);
        return Async\await($this->ibkr_unsubscribe($client, array( 'str' ), 'utr', array( 'topic' => 'myTrades' )));
    }

    public function handle_my_trades(Client $client, array $message) {
        //
        //     {
        //         "topic": "str",
        //         "args": [
        //             {
        //                 "execution_id": "0000e0d5.6576fd38.01.01",
        //                 "symbol": "AAPL",
        //                 "side": "B",
        //                 "order_description": "Bot 5 @ 192.26 on ISLAND",
        //                 "trade_time_r": 1702319146000,
        //                 "size": 5,
        //                 "price": "192.26",
        //                 "order_ref": "my-id",
        //                 "exchange": "ISLAND",
        //                 "net_amount": 961.3,
        //                 "account": "U1234567",
        //                 "conid": 265598
        //             }
        //         ]
        //     }
        //
        $args = $this->safe_list($message, 'args', array());
        $argsLength = count($args);
        if ($argsLength === 0) {
            return;
        }
        if ($this->myTrades === null) {
            $limit = $this->safe_integer($this->options, 'tradesLimit', 1000);
            $this->myTrades = new ArrayCacheBySymbolById($limit);
        }
        $trades = $this->myTrades;
        // with realtimeUpdatesOnly the past executions replayed by the server are dropped, trade_time_r has a second precision
        $subscription = $this->safe_dict($client->subscriptions, 'str', array());
        $realtimeUpdatesOnly = $this->safe_bool($subscription, 'realtimeUpdatesOnly', false);
        $threshold = null;
        if ($realtimeUpdatesOnly) {
            $subscribedAt = $this->safe_integer($subscription, 'subscribedAt');
            if ($subscribedAt !== null) {
                $threshold = $this->parse_to_int($subscribedAt / 1000) * 1000;
            }
        }
        // the same execution can be sent several times, first without the commission, then with it, then again unchanged,
        // an execution identical to the cached one with the same id is not emitted again
        $options = $this->safe_dict($this->options, 'watchMyTrades', array());
        $skipDuplicates = $this->safe_bool($options, 'skipDuplicates', true);
        $symbols = array();
        for ($i = 0; $i < count($args); $i++) {
            $rawTrade = $args[$i];
            $trade = $this->parse_trade($rawTrade);
            $tradeTimestamp = $trade['timestamp'];
            if (($threshold !== null) && ($tradeTimestamp !== null) && ($tradeTimestamp < $threshold)) {
                continue;
            }
            if ($skipDuplicates) {
                $cachedBySymbol = $this->safe_dict($trades->hashmap, $trade['symbol'], array());
                $cached = $this->safe_dict($cachedBySymbol, $trade['id']);
                if ($cached !== null) {
                    $cachedInfo = $this->safe_dict($cached, 'info', array());
                    if ($this->json($cachedInfo) === $this->json($rawTrade)) {
                        continue;
                    }
                }
            }
            $trades->append($trade);
            $tradeSymbol = $trade['symbol'];
            $symbols[$tradeSymbol] = true;
        }
        $keys = is_array($symbols) ? array_keys($symbols) : array();
        $keysLength = count($keys);
        if ($keysLength === 0) {
            return;
        }
        $client->resolve($trades, 'myTrades');
        for ($i = 0; $i < count($keys); $i++) {
            $client->resolve($trades, 'myTrades::' . $keys[$i]);
        }
    }

    public function watch_balance($params = array()): PromiseInterface {
        return Async\async(self::do_watch_balance(...))($params);
    }

    private function do_watch_balance($params = array()) {
        /**
         * watch $balance and get the amount of funds available for trading or funds locked in orders, the cash comes from the account ledger stream, the first call takes a fetchBalance $snapshot for the holdings and the locked amounts
         *
         * @see https://www.interactivebrokers.com/docs/web-api/ws/account-ledger
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->accountId] the account id, defaults to $options["accountId"]
         * @return {array} a ~@link https://docs.ccxt.com/?id=$balance-structure $balance structure~
         */
        Async\await($this->load_markets());
        list($accountId, $query) = Async\await($this->loadAccountId($params));
        $url = Async\await($this->ibkr_connect());
        $client = $this->client($url);
        $messageHash = 'balance';
        $subscribeHash = 'sld::' . $accountId;
        if (!(is_array($client->subscriptions) && array_key_exists($subscribeHash ?? '', $client->subscriptions))) {
            $options = $this->safe_dict($this->options, 'watchBalance', array());
            $fetchBalanceSnapshot = $this->safe_bool($options, 'fetchBalanceSnapshot', true);
            if ($fetchBalanceSnapshot) {
                $snapshotRequest = array(
                    'accountId' => $accountId,
                );
                $snapshot = Async\await($this->fetch_balance($this->extend($query, $snapshotRequest)));
                // typed copy: the statically typed ports keep this.balance as a dictionary
                $snapshotBalance = $this->extend(array(), $snapshot);
                $this->balance = $snapshotBalance;
            }
        }
        // reusableFuture (), not watch () - the connection is already open (ibkrConnect), and go's watch () yields a channel
        $future = $client->reusableFuture($messageHash);
        $emptyArgs = '{}'; // a separate literal, the php transpiler turns '+{}' into '+array()'
        Async\await($this->ibkr_subscribe($client, $subscribeHash, 'sld+' . $accountId . '+' . $emptyArgs, array( 'accountId' => $accountId )));
        $balance = Async\await($future);
        return $balance;
    }

    public function un_watch_balance($params = array()): PromiseInterface {
        return Async\async(self::do_un_watch_balance(...))($params);
    }

    private function do_un_watch_balance($params = array()) {
        /**
         * unWatches the balance of the account
         *
         * @see https://www.interactivebrokers.com/docs/web-api/ws/account-ledger
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->accountId] the account id, defaults to options["accountId"]
         * @return {boolean} true
         */
        list($accountId, $query) = Async\await($this->loadAccountId($params));
        $url = Async\await($this->ibkr_connect());
        $client = $this->client($url);
        $this->balance = array();
        $emptyArgs = '{}'; // a separate literal, the php transpiler turns '+{}' into '+array()'
        return Async\await($this->ibkr_unsubscribe($client, array( 'balance', 'sld::' . $accountId ), 'uld+' . $accountId . '+' . $emptyArgs, $query));
    }

    public function handle_balance(Client $client, array $message) {
        //
        //     {
        //         "result": [
        //             { "acctCode": "U1234567", "cashbalance": 2.0201311791131118E8, "key": "LedgerListBASE", "secondKey": "BASE", "settledCash": 2.02E8, "timestamp": 1700248325, ... },
        //             { "acctCode": "U1234567", "cashbalance": 1000.0, "key": "LedgerListUSD", "secondKey": "USD", "timestamp": 1700248325, ... },
        //             { "key": "LedgerListEUR", "timestamp": 1700248325 }
        //         ],
        //         "topic": "sld+U1234567"
        //     }
        //
        $result = $this->safe_list($message, 'result', array());
        $changed = false;
        $timestamp = null;
        for ($i = 0; $i < count($result); $i++) {
            $entry = $result[$i];
            $timestamp = $this->safe_timestamp($entry, 'timestamp', $timestamp);
            $cash = $this->safe_string($entry, 'cashbalance');
            if ($cash === null) {
                continue; // unchanged since the previous message
            }
            $key = $this->safe_string($entry, 'key', '');
            $currencyId = $this->safe_string($entry, 'secondKey', str_replace('LedgerList', '', $key));
            if ($currencyId === 'BASE') {
                continue; // aggregated entry in the account base currency
            }
            $code = $this->safe_currency_code($currencyId);
            $account = $this->safe_dict($this->balance, $code, $this->account());
            $account['total'] = $cash;
            $account['free'] = null; // recomputed from total - used
            $this->balance[$code] = $account;
            $changed = true;
        }
        if (!$changed && (is_array($this->balance) && array_key_exists('info' ?? '', $this->balance))) {
            return;
        }
        $this->balance['info'] = $message;
        $this->balance['timestamp'] = $timestamp;
        $this->balance['datetime'] = $this->iso8601($timestamp);
        $this->balance = $this->safe_balance($this->balance);
        $client->resolve($this->balance, 'balance');
    }

    public function handle_session_status(Client $client, array $message) {
        //
        //     { "topic": "sts", "args": { "authenticated": true, "competing": false, "message": "", "fail": "", "serverName": "...", "serverVersion": "..." } }
        //
        $args = $this->safe_dict($message, 'args', array());
        $authenticated = $this->safe_bool($args, 'authenticated');
        if ($authenticated === null) {
            return;
        }
        if ($authenticated) {
            $client->subscriptions['ibkrAuthenticated'] = true;
            $client->resolve(true, 'authenticated');
        } else {
            $client->subscriptions['ibkrAuthenticated'] = false;
            if ($this->safe_bool($this->options, 'useGateway', false)) {
                // e.g. taken over by a login with the same username elsewhere, see options.autoRegainSession
                $this->ibkrGatewayOnSessionLost();
            }
            $error = new AuthenticationError($this->id . ' the brokerage session is not authenticated ' . $this->json($message));
            $client->reject($error);
        }
    }

    public function handle_error_message(Client $client, array $message): bool {
        //
        //     { "topic": "smd+123", "error": "..." }
        //
        $errorMessage = $this->safe_string($message, 'error');
        if ($errorMessage === null) {
            return false;
        }
        $feedback = $this->id . ' ' . $this->json($message);
        try {
            $this->throw_broadly_matched_exception($this->exceptions['broad'], $errorMessage, $feedback);
            throw new ExchangeError($feedback);
        } catch (Exception $error) {
            $client->reject($error);
        }
        return true;
    }

    public function ping(Client $client) {
        // https://www.interactivebrokers.com/docs/web-api/ws/ping - "tic" keeps the websocket session alive, no response is sent
        return 'tic';
    }

    public function handle_text_message(Client $client, string $message) {
        // plain text frames carry no data, but like every message they prove the connection is alive
        $client->lastPong = $this->milliseconds();
    }

    public function handle_message(Client $client, array $message) {
        //
        // every message (including the 10 second system heartbeats) proves the connection is alive
        //
        //     { "topic": "system", "success": "username" }
        //     { "topic": "system", "hb": 1702334859712 }
        //
        $client->lastPong = $this->milliseconds();
        if ($this->handle_error_message($client, $message)) {
            return;
        }
        $topic = $this->safe_string($message, 'topic', '');
        if (($topic === 'system') && !$this->safe_bool($client->subscriptions, 'ibkrConnected', false)) {
            $client->subscriptions['ibkrConnected'] = true;
            $client->resolve(true, 'connected');
        }
        if (str_starts_with($topic, 'smd+')) {
            $this->handle_ticker($client, $message);
        } elseif (str_starts_with($topic, 'smh+')) {
            $this->handle_ohlcv($client, $message);
        } elseif (str_starts_with($topic, 'sbd+')) {
            $this->handle_order_book($client, $message);
        } elseif ($topic === 'sor') {
            $this->handle_orders($client, $message);
        } elseif ($topic === 'str') {
            $this->handle_my_trades($client, $message);
        } elseif (str_starts_with($topic, 'sld+')) {
            $this->handle_balance($client, $message);
        } elseif ($topic === 'sts') {
            $this->handle_session_status($client, $message);
        }
        // system only marks the connection as open, act, blt, ntf, spl and ssd are not used
    }
}
